 @Override protected void onActivityResult(int request,int result,android.content.Intent data){super.onActivityResult(request,result,data);if(request==43){if(result==RESULT_OK&&data!=null)collageDialog(data);return;}if(request!=42||result!=RESULT_OK||data==null||data.getData()==null)return;android.net.Uri file=data.getData();String mime=getContentResolver().getType(file);if(!"application/pdf".equals(mime)&&!"image/jpeg".equals(mime)){printStatus.setText("Format belum didukung");return;}showSimplePreview(file,mime);}
 @Override protected void onNewIntent(android.content.Intent intent){super.onNewIntent(intent);setIntent(intent);importExternal(intent);}
 void importExternal(android.content.Intent intent){
 if(intent==null)return;String action=intent.getAction();android.net.Uri uri=null;
 if(android.content.Intent.ACTION_VIEW.equals(action))uri=intent.getData();
 else if(android.content.Intent.ACTION_SEND.equals(action))uri=intent.getParcelableExtra(android.content.Intent.EXTRA_STREAM);
 if(uri==null||!"content".equals(uri.getScheme()))return;
 String mime=getContentResolver().getType(uri);if(mime==null)mime=intent.getType();
 if(!"application/pdf".equals(mime)&&!"image/jpeg".equals(mime)){printStatus.setText("Pilih PDF atau foto JPEG");return;}
 showSimplePreview(uri,mime);
 }
