 static float[] paperMm(String media){if(media.equals("custom_f4_210x330mm"))return new float[]{210,330};if(media.equals("na_legal_8.5x14in"))return new float[]{215.9f,355.6f};if(media.equals("na_index-4x6_4x6in"))return new float[]{101.6f,152.4f};return new float[]{210,297};}
 static android.graphics.RectF[] passportCells(int size,String media,int margin,int count,int gap)throws IOException{
 float[] paper=paperMm(media);int w=new int[]{0,20,30,40}[size],h=new int[]{0,30,40,60}[size],m=Math.max(5,margin);
 int cols=(int)Math.floor((paper[0]-2*m+gap)/(w+gap)),rows=(int)Math.floor((paper[1]-2*m+gap)/(h+gap));
 if(count<1||cols<1||rows<1||count>cols*rows)throw new IOException("Maksimum "+Math.max(0,cols*rows)+" foto per lembar");
 android.graphics.RectF[] cells=new android.graphics.RectF[count];for(int i=0;i<count;i++){float x=m+(i%cols)*(w+gap),y=m+(i/cols)*(h+gap);cells[i]=new android.graphics.RectF(x,y,x+w,y+h);}return cells;
 }
 InputStream passportInput(android.net.Uri file,int rotation,int size,String media,int margin,int count,int gap,int anchorX,int anchorY)throws IOException{
 float[] paper=paperMm(media);float unit=72f/25.4f;
 android.graphics.RectF[] cells=passportCells(size,media,margin,count,gap);
 try(InputStream in=photoInput(file,"image/jpeg",rotation,size==2?3:2,anchorX,anchorY)){
 android.graphics.Bitmap bitmap=android.graphics.BitmapFactory.decodeStream(in);if(bitmap==null)throw new IOException("Foto tidak dapat dibaca");
 android.graphics.pdf.PdfDocument pdf=new android.graphics.pdf.PdfDocument();
 try{android.graphics.pdf.PdfDocument.Page page=pdf.startPage(new android.graphics.pdf.PdfDocument.PageInfo.Builder(Math.round(paper[0]*unit),Math.round(paper[1]*unit),1).create());android.graphics.Canvas canvas=page.getCanvas();canvas.drawColor(android.graphics.Color.WHITE);for(android.graphics.RectF cell:cells)canvas.drawBitmap(bitmap,null,new android.graphics.RectF(cell.left*unit,cell.top*unit,cell.right*unit,cell.bottom*unit),new android.graphics.Paint(android.graphics.Paint.FILTER_BITMAP_FLAG));pdf.finishPage(page);ByteArrayOutputStream bytes=new ByteArrayOutputStream();pdf.writeTo(bytes);return new ByteArrayInputStream(bytes.toByteArray());}finally{pdf.close();bitmap.recycle();}
 }
 }
 InputStream photoInput(android.net.Uri file,String mime,int rotation,int crop,int anchorX,int anchorY)throws IOException{
 if((rotation==0&&crop==0)||!"image/jpeg".equals(mime))return getContentResolver().openInputStream(file);
 if(android.os.Build.VERSION.SDK_INT<28)throw new IOException("Rotasi memerlukan Android 9");
 android.graphics.Bitmap original=android.graphics.ImageDecoder.decodeBitmap(android.graphics.ImageDecoder.createSource(getContentResolver(),file),(decoder,header,source)->{int w=header.getSize().getWidth(),h=header.getSize().getHeight();double scale=Math.min(1.0,Math.min(4200.0/Math.max(w,h),Math.sqrt(12000000.0/((double)w*h))));decoder.setTargetSize(Math.max(1,(int)(w*scale)),Math.max(1,(int)(h*scale)));decoder.setAllocator(android.graphics.ImageDecoder.ALLOCATOR_SOFTWARE);});
 android.graphics.Bitmap edited=null;try{edited=editBitmap(original,rotation,crop,anchorX,anchorY);ByteArrayOutputStream bytes=new ByteArrayOutputStream();if(!edited.compress(android.graphics.Bitmap.CompressFormat.JPEG,95,bytes))throw new IOException("Edit foto gagal");return new ByteArrayInputStream(bytes.toByteArray());}finally{if(edited!=null&&edited!=original)edited.recycle();original.recycle();}
 }
 static int[] cropBounds(int w,int h,int crop,int anchorX,int anchorY){
 if(crop==0)return new int[]{0,0,w,h};
 float ratio=new float[]{0,1f,2f/3,3f/4,4f/6,4f/3,3f/2}[crop];
 int cw=w,ch=h;
 if(w/(float)h>ratio)cw=Math.max(1,Math.round(h*ratio));else ch=Math.max(1,Math.round(w/ratio));
 return new int[]{Math.round((w-cw)*anchorX/100f),Math.round((h-ch)*anchorY/100f),cw,ch};
 }
 static android.graphics.Bitmap editBitmap(android.graphics.Bitmap original,int rotation,int crop,int anchorX,int anchorY){
 android.graphics.Matrix matrix=new android.graphics.Matrix();matrix.postRotate(rotation);
 android.graphics.Bitmap rotated=rotation==0?original:android.graphics.Bitmap.createBitmap(original,0,0,original.getWidth(),original.getHeight(),matrix,true);
 if(crop==0)return rotated;
 int[] bounds=cropBounds(rotated.getWidth(),rotated.getHeight(),crop,anchorX,anchorY);
 android.graphics.Bitmap result=android.graphics.Bitmap.createBitmap(rotated,bounds[0],bounds[1],bounds[2],bounds[3]);
 if(rotated!=original&&rotated!=result)rotated.recycle();return result;
 }
