ange.setHint("Halaman PDF (kosong = semua, contoh 2-5)");range.setSingleLine(true);l.addView(range);android.content.SharedPreferences prefs=getPreferences(0);Spinner[] settings={paper,quality,color,type,margin,scaling};String[] keys={"paper","quality","color","type","margin","scaling"};for(int i=0;i<settings.length;i++){final String key=keys[i];Spinner setting=settings[i];setting.setSelection(Math.max(0,Math.min(setting.getCount()-1,prefs.getInt(key,0))));setting.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onItemSelected(android.widget.AdapterView<?> p,android.view.View v,int pos,long id){prefs.edit().putInt(key,pos).apply();}public void onNothingSelected(android.widget.AdapterView<?> p){}});}Button reset=new Button(this);reset.setText("Reset pengaturan cetak");l.addView(reset);styleAction(reset,false);reset.setOnClickListener(v->{for(Spinner setting:settings)setting.setSelection(0);copies.setText("1");range.setText("");});
 for(int i=settingsStart;i<l.getChildCount();i++)l.getChildAt(i).setVisibility(android.view.View.GONE);
 section(l,"02  Pilih dan cetak");Button print=new Button(this);print.setText("Pilih PDF / JPEG untuk cetak");l.addView(print);styleAction(print,true);print.setOnClickListener(v->{android.content.Intent i=new android.content.Intent(android.content.Intent.ACTION_OPEN_DOCUMENT);i.setType("*/*");i.putExtra(android.content.Intent.EXTRA_MIME_TYPES,new String[]{"application/pdf","image/jpeg"});i.addCategory(android.content.Intent.CATEGORY_OPENABLE);startActivityForResult(i,42);});Button collage=new Button(this);collage.setText("Kolase beberapa foto JPEG");l.addView(collage);styleAction(collage,true);collage.setVisibility(android.view.View.GONE);collage.setOnClickListener(v->{android.content.Intent i=new android.content.Intent(android.content.Intent.ACTION_OPEN_DOCUMENT);i.setType("image/jpeg");i.putExtra(android.content.Intent.EXTRA_ALLOW_MULTIPLE,true);i.addCategory(android.content.Intent.CATEGORY_OPENABLE);startActivityForResult(i,43);});Button scan=new Button(this);scan.setText("Cari printer Wi-Fi");l.addView(scan);styleAction(scan,false);l.removeView(scan);l.addView(scan,l.indexOfChild(probe));scan.setOnClickListener(v->discover(uri,status));section(l,"04  Diagnostik dan aplikasi");Button maintenance=new Button(this);maintenance.setText("Status dan perawatan printer");l.addView(maintenance);styleAction(maintenance,false);maintenance.setOnClickListener(v->{String address=uri.getText().toString().trim();maintenance.setEnabled(false);new Thread(()->{String report;try{report=Ipp.probe(address);}catch(Exception e){report="Gagal: "+e.getMessage();}String result=report;runOnUiThread(()->{maintenance.setEnabled(true);if(!isFinishing())new AlertDialog.Builder(this).setTitle("Diagnostik printer").setMessage(result+"\n\nHead cleaning, nozzle check dan alignment belum tersedia: protokol printer belum terverifikasi. Gunakan panel printer atau utilitas resmi HP.").setPositiveButton("Tutup",null).show();});}).start();});
